jedi.api.completion.search_in_module:
def search_in_module(inference_state, module_context, names, wanted_names, wanted_type, complete=False, fuzzy=False, ignore_imports=False, convert=False):
    for s in wanted_names[:-1]:
        new_names = []
        for n in names:
            if s == n.string_name:
                if (n.tree_name is not None and n.api_type in ('module', 'namespace') and ignore_imports):
                    continue
                new_names += complete_trailer(module_context, n.infer())
        debug.dbg('dot lookup on search %s from %s', new_names, names[:10])
        names = new_names
    last_name = wanted_names[-1].lower()
    for n in names:
        string = n.string_name.lower()
        if ((complete and helpers.match(string, last_name, fuzzy=fuzzy)) or (not complete and string == last_name)):
            if isinstance(n, SubModuleName):
                names = [v.name for v in n.infer()]
            else:
                names = [n]
            if convert:
                names = convert_names(names)
            for n2 in names:
                if complete:
                    def_ = classes.Completion(inference_state, n2, stack=None, like_name_length=len(last_name), is_fuzzy=fuzzy)
                else:
                    def_ = classes.Name(inference_state, n2)
                if (not wanted_type or wanted_type == def_.type):
                    yield def_

jedi.inference.compiled.subprocess.funct:
def _zip_list_subdirectory(zip_path, zip_subdir_path):
    zip_file = ZipFile(zip_path)
    zip_subdir_path = Path(zip_subdir_path)
    zip_content_file_paths = zip_file.namelist()
    for raw_file_name in zip_content_file_paths:
        file_path = Path(raw_file_name)
        if file_path.parent == zip_subdir_path:
            file_path = file_path.relative_to(zip_subdir_path)
            yield (file_path.name, raw_file_name.endswith('/'))

def _iter_module_names(inference_state, paths):
    for path in paths:
        try:
            dir_entries = ((entry.name, entry.is_dir()) for entry in os.scandir(path))
        except OSError:
            try:
                zip_import_info = zipimporter(path)
                dir_entries = _zip_list_subdirectory(zip_import_info.archive, zip_import_info.prefix)
            except ZipImportError:
                debug.warning('Not possible to list directory: %s', path)
                continue
        for (name, is_dir) in dir_entries:
            if is_dir:
                if (name != '__pycache__' and name.isidentifier()):
                    yield name
            else:
                if name.endswith('.pyi'):
                    modname = name[:-4]
                else:
                    modname = inspect.getmodulename(name)
                if (modname and '.' not in modname):
                    if modname != '__init__':
                        yield modname

parso.cache._get_cache_directory_path:
def _get_cache_directory_path(cache_path=None):
    if cache_path is None:
        cache_path = _default_cache_path
    directory = cache_path.joinpath(_VERSION_TAG)
    if not directory.exists():
        os.makedirs(directory)
    return directory

jedi.plugins.stdlib.argument_clinic.f.wr:
def wrapper(value, arguments, callback):
    try:
        args = tuple(iterate_argument_clinic(value.inference_state, arguments, clinic_string))
    except ParamIssue:
        return NO_VALUES
    debug.dbg('builtin start %s' % value, color='MAGENTA')
    kwargs = {}
    if want_context:
        kwargs['context'] = arguments.context
    if want_value:
        kwargs['value'] = value
    if want_inference_state:
        kwargs['inference_state'] = value.inference_state
    if want_arguments:
        kwargs['arguments'] = arguments
    if want_callback:
        kwargs['callback'] = callback
    result = func(*args, **kwargs)
    debug.dbg('builtin end: %s', result, color='MAGENTA')
    return result
